import React, { useState, useEffect, useMemo } from 'react';
import { getAllUsers, updateUserStatus } from '../../api/listingService';
import { useAuth } from '../../context/AuthContext';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { Badge } from '../ui/badge';
import { User, Calendar, XCircle, CheckCircle, AlertTriangle, Trash2, Building, Shield, Search } from 'lucide-react';
import { toast } from "sonner";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '../ui/dialog';
import Pagination from '../ui/Pagination';

const UserManagement = () => {
    const { user } = useAuth();
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);
    const [selectedUser, setSelectedUser] = useState(null);
    const [showBanDialog, setShowBanDialog] = useState(false);
    const [showDeleteDialog, setShowDeleteDialog] = useState(false);
    const [showUnbanInfo, setShowUnbanInfo] = useState(false);
    const [currentPage, setCurrentPage] = useState(1);
    const [searchQuery, setSearchQuery] = useState('');
    const itemsPerPage = 8;

    const fetchAllUsers = async () => {
        try {
            setLoading(true);
            const allUsers = await getAllUsers();
            setUsers(allUsers || []);
        } catch (error) {
            console.error(error);
            toast.error('Failed to fetch users.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchAllUsers();
    }, []);

    const handleUpdateUserStatus = async (username, displayName, action) => {
        if (action === 'delete' && user?.username === username) {
            toast.error("You cannot delete your own account.");
            return;
        }

        const toastId = toast.loading(`Requesting to ${action} user '${displayName}'...`);
        setActionLoading(true);

        try {
            await updateUserStatus(username, action);

            if (action === 'delete') {
                toast.success(`User '${displayName}' has been deleted successfully.`, { id: toastId });
            } else {
                toast.success(`User '${displayName}' has been successfully ${action === 'suspend' ? 'suspended' : 'activated'}.`, { id: toastId });
            }

            fetchAllUsers();

            if (action === 'suspend') {
                setShowUnbanInfo(true);
            }
        } catch (error) {
            toast.error(error.message || 'Failed to update user status.', { id: toastId });
        } finally {
            setActionLoading(false);
        }
    };


    const filteredUsers = useMemo(() => {
        if (!searchQuery.trim()) return users;
        const query = searchQuery.toLowerCase();
        return users.filter(user => 
            user.name?.toLowerCase().includes(query) || 
            user.email?.toLowerCase().includes(query)
        );
    }, [users, searchQuery]);

    const paginatedFilteredUsers = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return filteredUsers.slice(startIndex, startIndex + itemsPerPage);
    }, [filteredUsers, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    if (loading) {
        return (
            <div className="container mx-auto px-4 py-8">
                <div className="bg-white rounded-xl border-2 border-gray-200 p-6">
                    <div className="h-8 w-48 bg-gray-200 rounded animate-pulse mb-2"></div>
                    <div className="h-5 w-64 bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="h-10 w-full bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="space-y-3">
                        {[1, 2, 3, 4, 5, 6, 7, 8].map(i => (
                            <div key={i} className="h-16 w-full bg-gray-100 rounded-lg flex items-center px-4 animate-pulse">
                                <div className="w-10 h-10 bg-gray-200 rounded-full mr-4"></div>
                                <div className="flex-1">
                                    <div className="h-4 w-32 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-3 w-48 bg-gray-200 rounded"></div>
                                </div>
                                <div className="h-6 w-20 bg-gray-200 rounded"></div>
                                <div className="h-8 w-16 bg-gray-200 rounded ml-4"></div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8">
            <Card className="border-2 border-gray-200">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2 text-2xl">
                        <User className="h-6 w-6 text-blue-600" />
                        User Management
                    </CardTitle>
                    <p className="text-gray-600 mt-2">
                        Manage all users, roles, and account statuses
                    </p>
                </CardHeader>
                <CardContent>
                    <div className="mb-4">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <input
                                type="text"
                                placeholder="Search by name or email..."
                                value={searchQuery}
                                onChange={(e) => {
                                    setSearchQuery(e.target.value);
                                    setCurrentPage(1);
                                }}
                                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                            />
                        </div>
                    </div>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Profile</TableHead>
                                <TableHead>Email</TableHead>
                                <TableHead>Role</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead>Joined Date</TableHead>
                                <TableHead>Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {paginatedFilteredUsers.length > 0 ? paginatedFilteredUsers.map((user, index) => (
                                <TableRow key={user.userId || user.username || index}>
                                    <TableCell className="flex items-center gap-3">
                                        {user.profilePhoto ? (
                                            <img
                                                src={user.profilePhoto}
                                                alt={user.name || 'User'}
                                                className="h-10 w-10 rounded-full object-cover"
                                            />
                                        ) : (
                                            <div className="h-10 w-10 rounded-full bg-gray-200 flex items-center justify-center">
                                                <User className="h-5 w-5 text-gray-500" />
                                            </div>
                                        )}
                                        <span className="font-medium">{user.name || user.username || 'User'}</span>
                                    </TableCell>
                                    <TableCell>{user.email || 'N/A'}</TableCell>
                                    <TableCell>
                                        <Badge
                                            className={`flex items-center gap-1 whitespace-nowrap ${user.role === 'admin' ? 'bg-purple-100 text-purple-800 hover:bg-purple-100' :
                                                    user.role === 'owner' ? 'bg-blue-100 text-blue-800 hover:bg-blue-100' :
                                                        'bg-green-100 text-green-800 hover:bg-green-100'
                                                }`}
                                        >
                                            {user.role === 'admin' ? <Shield className="h-3 w-3" /> :
                                                user.role === 'owner' ? <Building className="h-3 w-3" /> :
                                                    <User className="h-3 w-3" />}
                                            <span className="capitalize">{user.role || 'student'}</span>
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        <Badge
                                            variant={user.status === 'CONFIRMED' || user.status === 'EXTERNAL_PROVIDER' ? 'default' :
                                                user.status === 'DISABLED' ? 'destructive' :
                                                    'secondary'}
                                            className="capitalize"
                                        >
                                            {(user.status || 'CONFIRMED').toLowerCase()}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex items-center gap-2">
                                            <Calendar className="h-4 w-4 text-gray-500" />
                                            <span>{user.createdDate ? new Date(user.createdDate).toLocaleDateString() : 'Recent'}</span>
                                        </div>
                                    </TableCell>
                                    <TableCell className="flex items-center gap-2">
                                        {user.role === 'admin' ? (
                                            <Badge variant="secondary" className="text-xs">Protected</Badge>
                                        ) : user.status === 'CONFIRMED' || user.status === 'EXTERNAL_PROVIDER' ? (
                                            <>
                                                <Button
                                                    variant="destructive"
                                                    size="sm"
                                                    disabled={actionLoading}
                                                    onClick={() => {
                                                        setSelectedUser(user);
                                                        setShowBanDialog(true);
                                                    }}
                                                >
                                                    <XCircle className="h-4 w-4 mr-1" />
                                                    Ban
                                                </Button>
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    className="text-red-600 border-red-200 hover:bg-red-50"
                                                    disabled={actionLoading}
                                                    onClick={() => {
                                                        setSelectedUser(user);
                                                        setShowDeleteDialog(true);
                                                    }}
                                                >
                                                    <Trash2 className="h-4 w-4 mr-1" />
                                                    Delete
                                                </Button>
                                            </>
                                        ) : user.status === 'DISABLED' ? (
                                            <>
                                                <Button
                                                    variant="default"
                                                    size="sm"
                                                    disabled={actionLoading}
                                                    onClick={() => {
                                                        handleUpdateUserStatus(
                                                            user.username,
                                                            user.name,
                                                            'activate'
                                                        );
                                                    }}
                                                >
                                                    <CheckCircle className="h-4 w-4 mr-1" />
                                                    Activate
                                                </Button>
                                                <Button
                                                    variant="outline"
                                                    size="sm"
                                                    className="text-red-600 border-red-200 hover:bg-red-50"
                                                    disabled={actionLoading}
                                                    onClick={() => {
                                                        setSelectedUser(user);
                                                        setShowDeleteDialog(true);
                                                    }}
                                                >
                                                    <Trash2 className="h-4 w-4 mr-1" />
                                                    Delete
                                                </Button>
                                            </>
                                        ) : null}
                                    </TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan={6} className="text-center py-8">
                                        <div className="flex flex-col items-center justify-center">
                                            <User className="h-8 w-8 text-gray-400 mb-2" />
                                            <p className="text-gray-500">{searchQuery ? 'No users found matching your search' : 'No users found'}</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                    <Pagination
                        currentPage={currentPage}
                        totalItems={filteredUsers.length}
                        itemsPerPage={itemsPerPage}
                        onPageChange={handlePageChange}
                    />
                </CardContent>
            </Card>

            {/* Ban Confirmation Dialog */}
            <Dialog open={showBanDialog} onOpenChange={setShowBanDialog}>
                <DialogContent className="sm:max-w-[500px]">
                    <DialogHeader>
                        <DialogTitle className="text-2xl text-red-600 flex items-center gap-2">
                            <XCircle className="h-6 w-6" />
                            Confirm Ban
                        </DialogTitle>
                        <DialogDescription className="mt-2">
                            Are you sure you want to ban <span className="font-semibold">{selectedUser?.name || 'this user'}</span>?
                            This action will restrict their access to the platform.
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowBanDialog(false)}>
                            Cancel
                        </Button>
                        <Button
                            variant="destructive"
                            disabled={actionLoading}
                            onClick={() => {
                                if (selectedUser) {
                                    handleUpdateUserStatus(
                                        selectedUser.username,
                                        selectedUser.name,
                                        'suspend'
                                    );
                                    setShowBanDialog(false);
                                }
                            }}
                        >
                            {actionLoading ? 'Banning...' : 'Confirm Ban'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation Dialog */}
            <Dialog open={showDeleteDialog} onOpenChange={setShowDeleteDialog}>
                <DialogContent className="sm:max-w-[500px]">
                    <DialogHeader>
                        <DialogTitle className="text-2xl text-red-600 flex items-center gap-2">
                            <Trash2 className="h-6 w-6" />
                            Confirm Delete User
                        </DialogTitle>
                        <DialogDescription className="mt-2">
                            Are you sure you want to delete <span className="font-semibold">{selectedUser?.name || 'this user'}</span>?
                            This action cannot be undone.
                        </DialogDescription>
                    </DialogHeader>
                    <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                        <p className="text-sm text-red-800 font-medium mb-2">This will:</p>
                        <ul className="text-sm text-red-700 list-disc list-inside space-y-1">
                            <li>Delete the user account from Cognito</li>
                            <li>Mark all their listings as unavailable</li>
                            <li>Remove all their booking requests</li>
                            <li>Permanently remove all user data</li>
                        </ul>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowDeleteDialog(false)}>
                            Cancel
                        </Button>
                        <Button
                            variant="destructive"
                            disabled={actionLoading}
                            onClick={() => {
                                if (selectedUser) {
                                    handleUpdateUserStatus(
                                        selectedUser.username,
                                        selectedUser.name,
                                        'delete'
                                    );
                                    setShowDeleteDialog(false);
                                }
                            }}
                        >
                            <Trash2 className="h-4 w-4 mr-1" />
                            {actionLoading ? 'Deleting...' : 'Delete User'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Unban Information Dialog */}
            <Dialog open={showUnbanInfo} onOpenChange={setShowUnbanInfo}>
                <DialogContent className="sm:max-w-[500px]">
                    <DialogHeader>
                        <DialogTitle className="text-2xl text-blue-600 flex items-center gap-2">
                            <AlertTriangle className="h-6 w-6" />
                            User Banned Successfully
                        </DialogTitle>
                        <DialogDescription className="mt-2">
                            The user has been banned from the platform. They will now have limited access (view only).
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="flex items-start gap-3">
                            <AlertTriangle className="h-5 w-5 text-amber-500 mt-0.5" />
                            <div>
                                <h4 className="font-medium text-gray-900">Unban Process</h4>
                                <p className="text-gray-600 text-sm mt-1">
                                    Banned users can request unban by contacting the admin through the following details:
                                </p>
                                <div className="mt-2 bg-blue-50 p-3 rounded-md">
                                    <p className="text-sm text-blue-800">Admin Name: Admin User</p>
                                    <p className="text-sm text-blue-800">Email: admin@dormanddish.com</p>
                                    <p className="text-sm text-blue-800">Phone: +91 9876543210</p>
                                </div>
                            </div>
                        </div>

                        <div className="flex items-start gap-3">
                            <CheckCircle className="h-5 w-5 text-green-500 mt-0.5" />
                            <div>
                                <h4 className="font-medium text-gray-900">Banned User Experience</h4>
                                <p className="text-gray-600 text-sm mt-1">
                                    Banned users can:
                                </p>
                                <ul className="list-disc list-inside text-gray-600 text-sm mt-1">
                                    <li>View listings</li>
                                    <li>Search properties</li>
                                    <li>View public information</li>
                                    <li>Cannot create listings</li>
                                    <li>Cannot book properties</li>
                                    <li>Cannot send booking requests</li>
                                </ul>
                            </div>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button onClick={() => setShowUnbanInfo(false)}>
                            Understood
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default UserManagement;